/**
 * Prompt Discovery Handler
 */
import { registerPrompt } from "../../mcp/index.js";
import { filenameToId } from "../discovery-utils.js";
export const promptHandler = {
    typeName: "prompt",
    validate: (item) => item !== null && typeof item === "object" && typeof item.getContent === "function",
    getId: (_item, file) => filenameToId(file),
    register: (id, prompt) => {
        const promptWithId = { ...prompt, id };
        registerPrompt(id, promptWithId);
        return promptWithId;
    },
    getResultMap: (result) => result.prompts,
};
